function prompt(a) {
  return `You are agent \`${a.key}\` in the pre-release simplification audit of the repository at ${ROOT}.

FIRST, read ${AUD}/brief-common.md in full. It carries the owner's intent in his own words, the hard rules (read-only, no builds/tests/browsers/DB, another session shares the tree), the complete methodology (reduction order, anti-gaming, dead-code rules, the simplification pass, the six LLM-bloat signatures, Next.js levers, tiering, the macro question), the exact finding format (section 7) and the report structure (section 8). Then read ${ROOT}/CLAUDE.md and ${ROOT}/AGENTS.md. Then the specs named below. Only then open your territory. Everything in the brief applies to you; this prompt adds your charter.

## Your charter
${a.charter}

## Your territory
${a.files}

## Not yours (a neighbour covers these; put cross-territory observations under "For other lenses" with file names)
${a.notYours}

## Specs and docs to read first
${a.specs}

## Leads from the tools (paths are relative to ${AUD}/)
${a.leads}

## The floor for your territory (answer all of these; they are not the ceiling - hunt beyond them)
${a.questions}

## Working notes
- Another session is active in this tree. \`git status --short\` currently shows their uncommitted edits to next.config.ts, src/lib/admin.ts, scripts/qa/phase7-probe.mjs, src/components/tour/manual-tour-entry.test.mjs and a new src/app/(main)/forbidden.tsx. Judge HEAD's version of any such file (\`git show HEAD:<path>\`) and mention the WIP; never touch it.
- The checklists in the brief are a floor. Where you are better placed than the orchestrator to judge something in your territory, judge it and say why.
- Be verbose in Evidence and Notes, precise in Where and What to do. Numbers over adjectives.
- Do not run npm scripts, tsc, builds, browsers, or anything that touches the database.

## Deliverable
Write your full report to ${AUD}/agents/${a.key}.md using the structure in brief-common.md section 8 and the finding format in section 7, with ids ${a.key}-01, ${a.key}-02, ... ordered biggest structural win first. Write it BEFORE returning; if you are running long, write a partial report early and overwrite it later, so nothing is lost if the session dies. Then return the structured summary (key, reportPath, counts, estimatedLinesSaved, up to six headline lines with finding ids, and gaps you did not get to).`
}

phase('Find')
const todo = AGENTS.filter((a) => !done.has(a.key))
// Waves of 6, not one big parallel(): on 2026-08-25 the first launch lost all 18 agents
// (~1.8M tokens) to a usage-limit cutoff with nothing on disk. A wave that finishes has
// its reports written; a later cutoff loses at most one wave.
log(`launching ${todo.length} agents in waves of 6 (skipping ${done.size}: ${[...done].join(', ') || 'none'})`)
const ok = []
for (let i = 0; i < todo.length; i += 6) {
  const wave = todo.slice(i, i + 6)
  log(`wave ${i / 6 + 1}: ${wave.map((a) => a.key).join(', ')}`)
  const results = await parallel(wave.map((a) => () => agent(prompt(a), { label: a.key, phase: 'Find', schema: SUMMARY })))
  ok.push(...results.filter(Boolean))
  log(`wave ${i / 6 + 1} done; ${ok.length}/${todo.length} returned so far`)
  if (wave.length > 1 && results.every((r) => !r)) {
    log('entire wave returned nothing - stopping so later waves are not fed into a dead usage limit')
    break
  }
}
log(`${ok.length}/${todo.length} agents returned; total findings ${ok.reduce((n, r) => n + (r.findings || 0), 0)}`)
return { returned: ok.map((r) => r.key), missing: todo.map((a) => a.key).filter((k) => !ok.some((r) => r.key === k)), summaries: ok }